use crate::models::category::Category; use crate::errors::{Result, AppError}; use tauri::State; use crate::database::Database; use rusqlite::params; #[tauri::command] pub fn get_categories(db: State<'_, Database>) -> Result<Vec<Category>> { let conn = db.get_connection()?; let mut stmt = conn.prepare("SELECT id, name, description, created_at, updated_at FROM categories ORDER BY name ASC")?; let categories = stmt.query_map([], |row| { Ok(Category { id: row.get(0)?, name: row.get(1)?, description: row.get(2)?, created_at: row.get(3)?, updated_at: row.get(4)? }) })?.collect::<std::result::Result<Vec<_>, _>>()?; Ok(categories) } #[tauri::command] pub fn create_category(db: State<'_, Database>, name: String, description: Option<String>) -> Result<Category> { let conn = db.get_connection()?; let mut stmt = conn.prepare("SELECT COUNT(*) FROM categories WHERE name = ?1")?; let count: i64 = stmt.query_row(params![name], |row| row.get(0))?; if count > 0 { return Err(AppError::Validation("Category name already exists.".into())); } conn.execute("INSERT INTO categories (name, description) VALUES (?1, ?2)", params![name, description])?; let id = conn.last_insert_rowid(); let category = conn.query_row("SELECT id, name, description, created_at, updated_at FROM categories WHERE id = ?1", params![id], |row| { Ok(Category { id: row.get(0)?, name: row.get(1)?, description: row.get(2)?, created_at: row.get(3)?, updated_at: row.get(4)? }) })?; Ok(category) } #[tauri::command] pub fn update_category(db: State<'_, Database>, id: i64, name: String, description: Option<String>) -> Result<Category> { let conn = db.get_connection()?; let mut stmt = conn.prepare("SELECT COUNT(*) FROM categories WHERE name = ?1 AND id != ?2")?; let count: i64 = stmt.query_row(params![name, id], |row| row.get(0))?; if count > 0 { return Err(AppError::Validation("Category name already exists.".into())); } conn.execute("UPDATE categories SET name = ?1, description = ?2, updated_at = CURRENT_TIMESTAMP WHERE id = ?3", params![name, description, id])?; let category = conn.query_row("SELECT id, name, description, created_at, updated_at FROM categories WHERE id = ?1", params![id], |row| { Ok(Category { id: row.get(0)?, name: row.get(1)?, description: row.get(2)?, created_at: row.get(3)?, updated_at: row.get(4)? }) })?; Ok(category) } #[tauri::command] pub fn delete_category(db: State<'_, Database>, id: i64) -> Result<()> { let conn = db.get_connection()?; let mut stmt = conn.prepare("SELECT COUNT(*) FROM products WHERE category_id = ?1")?; let count: i64 = stmt.query_row(params![id], |row| row.get(0))?; if count > 0 { return Err(AppError::BusinessRule("Cannot delete category because it is used by products.".into())); } conn.execute("DELETE FROM categories WHERE id = ?1", params![id])?; Ok(()) }
